/// <summary>
/// Developed for CB154_FreeItemExciseClaim
/// Extension calss for GUPDiscountClaimTransaction
/// </summary>
[ExtensionOf(tableStr(GUPDiscountClaimTransaction))]
final class METGUPDiscountClaimTransactionTbl_Extension
{
}

Method.Source:
    /// <summary>
    /// This method is COC on insert
    /// </summary>
    public void insert()
    {
        GupDiscountClaimTransaction gupDiscountClaimTran;
        SalesLine                   salesLine;
        METInventTable              mETinventTable;
        METExciseSiteDutySetup      mETExciseSiteDutySetup;
        METCustomExcise             customExcise;

        customExcise    = mETinventTable.customExcise();
        salesLine       = SalesLine::findInventTransId(this.InventTransId);
        mETinventTable  = METInventTable::find(salesLine.ItemId);

        // Setting up the Amount and METFreeItemExciseDuty fields
        select firstonly mETExciseSiteDutySetup
            where mETExciseSiteDutySetup.ItemId == salesLine.ItemId
            && mETExciseSiteDutySetup.SiteId == salesLine.inventDim().InventSiteId
            && mETExciseSiteDutySetup.DutyPerCase != 0;

        select firstonly RecId,METFreeItemExciseDuty from gupDiscountClaimTran
            where gupDiscountClaimTran.LedgerAccount   == this.LedgerAccount
               && gupDiscountClaimTran.InventTransId   == this.InventTransId;
        // Check to see if Item is marked for custom or excise and has a record in duty setup and in claim transation table
        if (gupDiscountClaimTran.RecId == 0 
            && mETExciseSiteDutySetup.RecId != 0 
            && (customExcise == METCustomExcise::C || customExcise == METCustomExcise::E))
        {
            this.Amount = this.Amount + (mETExciseSiteDutySetup.DutyPerCase  * salesLine.SalesQty);
            this.METFreeItemExciseDuty = mETExciseSiteDutySetup.DutyPerCase;
        }
        // Check to see if Item is marked for custom or excise and has a record in duty setup and excise is 0 in claim transation table
        else if (mETExciseSiteDutySetup.RecId != 0 
                && (customExcise == METCustomExcise::C || customExcise == METCustomExcise::E) 
                && gupDiscountClaimTran.METFreeItemExciseDuty == 0)
        {
            this.Amount = this.Amount + (mETExciseSiteDutySetup.DutyPerCase  * salesLine.SalesQty);
            this.METFreeItemExciseDuty = mETExciseSiteDutySetup.DutyPerCase;
        }

        next insert();
    }
